VAR p:vector; i,j,k,m,t:integer;
BEGIN
k:=0; i:=1; m:=n;
WHILE i<n DO
BEGIN
FOR j:=m DOWNTO i+1 DO
IF a[i]<a[j] THEN
BEGIN t:=a[i]; a[i]:=a[j]; a[j]:=t; k:=k+1;（(1)____）END;
REPEAT（(2)____）;
IF（(3)____）THEN（(4)____）
ELSE BEGIN m:=p[k]; k:=k-1; END;
UNTIL (i<m) OR (i=n);
IF （(5)___）
BEGIN t:=a[i];（(6)____）;（(7)____）END
END
END; 【上海海运学院 1997 七（14分）】

