程序.(a)
PROCEDURE oesort(VAR a:ARRAY[1..n] OF integer);
VAR flag:boolean; i,t:integer;
BEGIN
REPEAT
flag:=false;
FOR i:=1 TO n step 2 DO
IF(a[i]>a[i+1]) THEN
[flag:= (1)____; t:=a[i+1]; a[i+1]:=a[i]; (2)____]
FOR i:= (3)____ DO
IF (a[i]>a[i+1]) THEN
[flag:= (4)____ ; t:=a[i+1];a[i+1]:=a[i]; a[i]:=t;]
UNTIL (5)___ ;
END;
程序（b）
void oesort (int a[n])
{int flag,i,t;
do {flag=0;
for(i=1;i<n;i++,i++)
if(a[i]>a[i+1])
{flag=(1)__; t=a[i+1]; a[i+1]=a[i]; (2)____;}
for (3)____
if (a[i]>a[i+1])
{flag=(4)____;t=a[i+1]; a[i+1]=a[i]; a[i]=t;}
}while (5)_;
