BEGIN
top:=0; i:=1; { i指示待选物品}
WHILE (1)_______ AND(2)_______DO
[IF (3)______ OR (4)_______ AND (i<n)
THEN [top := (5)_______ ;stack[top] :=i;{第i件物品装入背包}
T:=T-w[i]];
