questions.text:
①二叉树用来表示表达式，因为需要保存各子树的值，修改二叉树的结点结构为(Lchild,Data,Val,Rchild)。其中Lchild,Rchild的意义同前，Val用来存放以该结点为根的子树的值，值的类型依具体情况而定。为了简便起见，算法假定所考虑的表达式只有+，-，*，/ 四种二目运算，且已表示成相应的二叉树。算法所计算的表达式值放在根结点的Val域中。
PROC Postorder-eval(t:ptrType)
BEGIN IF (t!=NULL)
BEGIN (1)_______; (2)_______;
CASE t^.data:
‘+’: t^.Val:=t^. Lchild^. Val + t^. Rchild ^. Val; BREAK;
‘-’: t^.Val:=t^. Lchild^. Val - t^. Rchild ^. Val; BREAK;
‘*’: t^.Val:=t^. Lchild^. Val * t^. Rchild ^. Val; BREAK;
‘/’: t^.Val:=t^. Lchild^. Val / t^. Rchild ^. Val; BREAK;
otherwise: (3)___; BREAK;
ENDCASE END
END;
②PROC Delete(x:datatype,A:tree)
BEGIN tempA:= (4)___;
WHILE (tempA^.Item!=x) AND (tempA!=NULL) DO
IF (x<tempA^.item) BEGIN r:=tempA; tempA:= (5)___; END
ELSE BEGIN r:=tempA;tempA:=tempA^.Rchild;END;//tempA为要删结点，r为tempA的父亲
IF (6)___ return(x);
IF (tempA^.Lchild!=NULL) AND (tempA^.rchild!=NULL)
BEGIN t:=tempA; q:=tempA^.Rchild;
WHILE (q^.Lchild!=NULL) DO BEGIN t:=q; q:=q^.Lchild; END;
t^.Lchild:= (7)___; //删去q
q^.Lchild :=tempA^.Lchild; q^.Rchild:=tempA^.Rchild;
IF (tempA^.item< r^.item) r^.Lchild := (8)_ ELSE r^.Rchild:=q //用q代替 tempA
END;
ELSE IF(tempA^.Lchild!=NULL) IF(tempA^.item<r^.item) r^.Lchild:=tempA^.Lchild
ELSE r^.Rchild:=tempA^.Lchild
ELSE IF(tempA^.Rchild!=NULL) IF(tempA^.item<r^.item) r^.Rchild:= (9)___
ELSE r^.Lchild:=tempA^.Rchild
ELSE //tempA为树叶
IF(10)_ r^.Lchild:=NULL ELSE r^.Rchild:=NULL
END; 【中山大学 1999 四、 (20分)】

