BT=NULL; //置空二叉树
BinTreeNode *p;
int k; istream ins(ls)； //把串ls定义为输入字符串流对象ins ;
char ch; ins>>ch; //从ins顺序读入一个字符
while (ch != ‘#’){ //逐个字符处理，直到遇到‘#’为止
switch(ch){
case ‘(’: (1)___；k=1; break;
case ‘)’: pop(s); break;
case’,’ : (2)___； break;
default :p=new BinTreeNode; (3)____;p->leftChild=NULL;p->rightChild=NULL;
if(BT==NULL) (4)___；else if (k==1) top(s)->leftChild=p;
else top(s)->rightChild=p;
}
(5)____; } } 【清华大学 2001 六、 (15分)】

